// Prototype object of the application: members assigned to a module-level object.
var http = require('http');
var Router = require('./router');
var verbs = require('./verbs');
var slice = Array.prototype.slice;

var app = exports = module.exports = {};

app.lazyrouter = function lazyrouter() {
  if (!this._router) {
    this._router = new Router();
  }
};

app.handle = function handle(req, res, done) {
  this._router.handle(req, res, done);
};

app.listen = function listen() {
  var server = http.createServer(this);
  return server.listen.apply(server, arguments);
};

verbs.forEach(function (verb) {
  app[verb] = function (path) {
    this.lazyrouter();
    var route = this._router.route(path);
    route[verb].apply(route, slice.call(arguments, 1));
    return this;
  };
});

app.use = function use(fn) {
  var path = '/';
  if (typeof fn !== 'function') {
    path = fn;
  }
  var fns = slice.call(arguments, 0);
  this.lazyrouter();
  var router = this._router;
  fns.forEach(function (f) {
    router.use(path, f);
  });
  return this;
};

app.keep = function keep(name, fn) {
  this.kept = fn;
  this.names = name;
};
